import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './nav.css';
import hatLogo from '../../img/hatLogo.png';

export default function Nav() {
    const [menuOpen, setMenuOpen] = useState(false);
    return (
        <nav className="nav">
            {/* Logo always visible */}
            <div className="nav-logo">
                <Link to="/">
                    <img src={hatLogo} alt="Logo" className="site-logo" />
                </Link>
            </div>

            {/* Desktop menu */}
            <ul className="nav-list">
                <li className="nav-item"><Link to="/breakfast">BREAKFAST</Link></li>
                <li className="nav-item"><Link to="/lunch">LUNCH</Link></li>
                <li className="nav-item"><Link to="/dinner">DINNER</Link></li>
                <li className="nav-item"><Link to="/snack">SNACK</Link></li>
            </ul>

            {/* Hamburger button */}
            <button
                className="hamburger"
                aria-label="Toggle menu"
                onClick={() => setMenuOpen(open => !open)}
            >
                <span className="hamburger-bar" />
                <span className="hamburger-bar" />
                <span className="hamburger-bar" />
            </button>

            {/* Mobile full-screen panel */}
            {menuOpen && (
                <div className="mobile-panel">
                    <button
                        className="close-btn"
                        aria-label="Close menu"
                        onClick={() => setMenuOpen(false)}
                    >
                        &times;
                    </button>
                    <ul className="mobile-nav-list">
                        <li><Link to="/" onClick={() => setMenuOpen(false)}>HOME</Link></li>
                        <li><Link to="/breakfast" onClick={() => setMenuOpen(false)}>BREAKFAST</Link></li>
                        <li><Link to="/lunch" onClick={() => setMenuOpen(false)}>LUNCH</Link></li>
                        <li><Link to="/dinner" onClick={() => setMenuOpen(false)}>DINNER</Link></li>
                        <li><Link to="/snack" onClick={() => setMenuOpen(false)}>SNACK</Link></li>
                    </ul>
                </div>
            )}
        </nav>
    );
}
